import re


_COUNSEL_HEAD_RE = re.compile(
    r"(?:^|\n)\s*(?:COUNSEL|ATTORNEYS?)\s*(?:\n|$)",
    re.IGNORECASE,
)
_APPELLANT_TAG_RE = re.compile(
    r"(?:\bfor\b(?:[ \t]*\n[ \t]*|[ \t]+)?)?(?:"
    r"Plaintiffs?[\s\-]*Appellants?|"
    r"Defendants?[\s\-]*Appellants?|"
    r"Petitioners?[\s\-]*Appellants?|"
    r"Respondents?[\s\-]*Appellants?|"
    r"Appellants?"
    r")\b\.?",
    re.IGNORECASE,
)
_SIDE_TAG_RE = re.compile(
    r"(?:\bfor\b(?:[ \t]*\n[ \t]*|[ \t]+)?)?(?:"
    r"Plaintiffs?[\s\-]*Appellants?|"
    r"Plaintiffs?[\s\-]*Appellees?|"
    r"Defendants?[\s\-]*Appellants?|"
    r"Defendants?[\s\-]*Appellees?|"
    r"Petitioners?[\s\-]*Appellants?|"
    r"Petitioners?[\s\-]*Appellees?|"
    r"Respondents?[\s\-]*Appellants?|"
    r"Respondents?[\s\-]*Appellees?|"
    r"Appellants?|"
    r"Appellees?"
    r")\b\.?",
    re.IGNORECASE,
)


def rule_first_listed_attorney_appellant(doc: dict) -> list[dict]:
    try:
        def norm(text: str) -> str:
            return re.sub(r"\s+", " ", (text or "")).strip()

        def first_attorney_from_block(block: str) -> str:
            text = norm(block)
            if not text:
                return ""

            text = re.sub(r"^\s*(?:and\s+)?", "", text, flags=re.IGNORECASE)
            text = text.split(";", 1)[0].strip()
            text = text.split(",", 1)[0].strip()
            text = re.split(r"\s+\band\b\s+", text, 1, flags=re.IGNORECASE)[0].strip()
            text = re.sub(r"\s*\((?:argued|lead|co[- ]?counsel|on brief|oral argument)\)\s*$", "", text, flags=re.IGNORECASE)
            text = re.sub(r"\s*\([^)]*\)\s*$", "", text).strip()
            text = re.sub(r"\s{2,}", " ", text).strip(" ,;:")
            if not text:
                return ""

            # If the extracted prefix still looks like an office or firm, keep it
            # only when there is no attorney-like name pattern to the left.
            return text

        def make_span(text: str, src: dict | None = None) -> dict:
            span = {"text": norm(text)}
            if src:
                for key in ("page_no", "paragraph_no", "line_no"):
                    if key in src:
                        span[key] = src[key]
            return span

        candidates: list[tuple[int, int, int, str, dict | None]] = []

        for source_key in ("pages", "paragraphs", "lines"):
            items = [item for item in (doc.get(source_key) or []) if isinstance(item, dict)]
            for idx, item in enumerate(items):
                raw_text = item.get("text") or ""
                text = norm(raw_text)
                if not text or "appellant" not in text.lower():
                    continue
                if not _COUNSEL_HEAD_RE.search(raw_text):
                    continue
                head = _COUNSEL_HEAD_RE.search(raw_text)
                search_start = head.end() if head else 0
                match = _APPELLANT_TAG_RE.search(raw_text, search_start)
                if match:
                    section = raw_text[search_start: match.start()]
                    if not section:
                        continue
                    prev = None
                    for side_match in _SIDE_TAG_RE.finditer(section):
                        prev = side_match
                    block = section[prev.end() :] if prev else section
                    block = block.strip()
                    if block:
                        candidates.append((0 if prev else 1, len(block), idx, block, item))

        raw_text = doc.get("text") or ""
        if isinstance(raw_text, str) and raw_text:
            head = _COUNSEL_HEAD_RE.search(raw_text)
            if head:
                search_start = head.end()
                match = _APPELLANT_TAG_RE.search(raw_text, search_start)
                if match:
                    section = raw_text[search_start: match.start()]
                    if section:
                        prev = None
                        for side_match in _SIDE_TAG_RE.finditer(section):
                            prev = side_match
                        block = section[prev.end() :] if prev else section
                        block = block.strip()
                        if block:
                            candidates.append((0 if prev else 1, len(block), 10000, block, None))

        if not candidates:
            for source_key in ("pages", "paragraphs", "lines"):
                items = [item for item in (doc.get(source_key) or []) if isinstance(item, dict)]
                combined = "\n".join((item.get("text") or "") for item in items if item.get("text"))
                if not combined:
                    continue
                head = _COUNSEL_HEAD_RE.search(combined)
                if not head:
                    continue
                search_start = head.end()
                match = _APPELLANT_TAG_RE.search(combined, search_start)
                if not match:
                    continue
                section = combined[search_start: match.start()]
                if not section:
                    continue
                prev = None
                for side_match in _SIDE_TAG_RE.finditer(section):
                    prev = side_match
                block = section[prev.end() :] if prev else section
                block = block.strip()
                if block:
                    candidates.append((0 if prev else 1, len(block), 20000, block, None))
                    break

        if not candidates:
            return []

        # Prefer the shortest prefix among plausible counsel blocks.
        candidates.sort(key=lambda item: (item[0], item[1], item[2]))
        for _, _, _, prefix, src in candidates:
            first = first_attorney_from_block(prefix)
            if first:
                return [make_span(first, src)]

        return []
    except Exception:
        return []

import re


_MONTH_NAME_RE = (
    r"(?:January|February|March|April|May|June|July|August|September|"
    r"October|November|December)"
)
_DATE_LONG_RE = re.compile(rf"^{_MONTH_NAME_RE} \d{{1,2}}, \d{{4}}$")
_DATE_ABBR_RE = re.compile(r"^[A-Z]{3} \d{1,2} \d{4}$")
_FILED_LONG_RE = re.compile(rf"^Filed ({_MONTH_NAME_RE} \d{{1,2}}, \d{{4}})$")
_FILED_ABBR_RE = re.compile(r"^Filed ([A-Z]{3} \d{1,2} \d{4})$")


def _as_int(value):
    try:
        return int(value)
    except Exception:
        return value


def _iter_header_lines(doc, max_pages=12, max_lines=100):
    pages = doc.get("pages") or []
    if pages:
        pages = sorted(pages, key=lambda x: _as_int(x.get("page_no", 0)))
        for page in pages[:max_pages]:
            page_no = _as_int(page.get("page_no", 0))
            text = page.get("text") or ""
            for idx, raw_line in enumerate(text.splitlines()[:max_lines], start=1):
                yield {"page_no": page_no, "line_no": idx, "text": raw_line}
        return

    lines = doc.get("lines") or []
    if lines:
        lines = sorted(
            lines,
            key=lambda x: (
                _as_int(x.get("page_no", 0)),
                _as_int(x.get("line_no", 0)),
            ),
        )
        current_page = None
        seen_pages = 0
        for line in lines:
            page_no = _as_int(line.get("page_no", 0))
            if page_no != current_page:
                current_page = page_no
                seen_pages += 1
                if seen_pages > max_pages:
                    break
            if _as_int(line.get("line_no", 0)) > max_lines:
                continue
            yield line


def _make_span(line, text=None):
    span = {
        "text": line.get("text", "") if text is None else text,
    }
    if "page_no" in line:
        span["page_no"] = line["page_no"]
    if "line_no" in line:
        span["line_no"] = line["line_no"]
    return span


def rule_on_what_date_was_this_opinion_filed(doc: dict) -> list[dict]:
    try:
        full_text = doc.get("text") or ""

        # Withdrawn-opinion orders often say "The Opinion filed <date> ..." and
        # the question is asking about that underlying opinion, not the order itself.
        m = re.search(
            rf"\bThe Opinion filed ({_MONTH_NAME_RE} \d{{1,2}}, \d{{4}}|[A-Z]{{3}} \d{{1,2}} \d{{4}})",
            full_text,
        )
        if m and (re.search(r"\bFILED\b", full_text) or re.search(r"\bAMENDED\b", full_text)):
            return [{"text": m.group(1)}]

        header_lines = list(_iter_header_lines(doc))
        if not header_lines:
            return []

        # The filing date usually appears on page 1 or 2, near the top of the header.
        for idx, line in enumerate(header_lines):
            text = (line.get("text") or "").strip()
            if not text:
                continue

            m = _FILED_LONG_RE.match(text) or _FILED_ABBR_RE.match(text)
            if m:
                return [_make_span(line, m.group(1))]

            if text == "FILED":
                for follow in header_lines[idx + 1 :]:
                    next_text = (follow.get("text") or "").strip()
                    if not next_text:
                        continue
                    if _DATE_LONG_RE.match(next_text) or _DATE_ABBR_RE.match(next_text):
                        return [_make_span(follow)]
                    break

            if _DATE_LONG_RE.match(text) or _DATE_ABBR_RE.match(text):
                return [_make_span(line)]

        # Fallback for unusual layouts.
        for pat in (_FILED_LONG_RE, _FILED_ABBR_RE):
            m = pat.search(full_text)
            if m:
                return [{"text": m.group(1)}]

        m = re.search(rf"\n({_MONTH_NAME_RE} \d{{1,2}}, \d{{4}}|[A-Z]{{3}} \d{{1,2}} \d{{4}})\n", full_text)
        if m:
            return [{"text": m.group(1)}]

        return []
    except Exception:
        return []
